#include <bits/stdc++.h>
#define endl '\n'
using namespace std;
using ll = long long;
const int N = 5e5 + 5, M = 20;
int n, m, u[N], v[N], head[N], dep[N], ans[N], p[N], a[N], b[N], l[N], s[N], h[N][M];
struct edge
{
    int v, next;
} e[N << 1];
deque<edge> g(1);
queue<int> q;
struct node
{
    int fa, fl;
    bool f1, f2;
    friend node operator+(const node &x, const node &y) { return {y.fa, !x.fl ? y.fl : (!y.fl ? x.fl : -1), x.f1 || y.f1, x.f2 || y.f2}; }
    friend node operator+=(node &x, const node &y) { return x = x + y; }
} st[N][M];
void add(int u, int v)
{
    static int cnt = 0;
    e[++cnt] = {v, head[u]};
    head[u] = cnt;
}
void add2(int x, int k, int t)
{
    g.push_back({t, h[x][k]});
    h[x][k] = (int)g.size() - 1;
}
void build()
{
    int t = 1;
    p[1] = 1;
    for (int j = 1; j <= t; ++j)
    {
        for (int i = head[p[j]]; i; i = e[i].next)
        {
            if (e[i].v == st[p[j]][0].fa)
                continue;
            p[++t] = e[i].v;
            dep[e[i].v] = dep[p[j]] + 1;
            st[e[i].v][0] = {p[j], (i + 1) / 2, 0, 0};
            for (int k = 1; (1 << k) <= dep[e[i].v]; ++k)
            {
                st[e[i].v][k] = st[e[i].v][k - 1] + st[st[e[i].v][k - 1].fa][k - 1];
                add2(e[i].v, k - 1, e[i].v);
                add2(st[e[i].v][k - 1].fa, k - 1, e[i].v);
            }
        }
    }
}
int lca(int x, int y)
{
    if (dep[x] < dep[y])
        swap(x, y);
    for (int d = dep[x] - dep[y]; d; d &= d - 1)
        x = st[x][__builtin_ctz(d)].fa;
    if (x == y)
        return x;
    for (int k = M - 1; k >= 0; --k)
    {
        if (st[x][k].fa != st[y][k].fa)
            x = st[x][k].fa, y = st[y][k].fa;
    }
    return st[x][0].fa;
}
void init() {}
int cnt(int fl) { return fl == -1 ? 2 : !!fl; }
node query(int x, int p, int i = 0)
{
    node res = {x, 0, 0, 0};
    while (x != p)
    {
        int k = __lg(dep[x] - dep[p]);
        if (i)
        {
            add2(x, k, -i);
            s[i] += cnt(st[x][k].fl);
        }
        res += st[x][k];
        x = st[x][k].fa;
    }
    return res;
}
void update(int x, int k, node cur)
{
    node old = st[x][k];
    if (old.fl == cur.fl && old.f1 == cur.f1 && old.f2 == cur.f2)
        return;
    st[x][k] = cur;
    for (int j = h[x][k], d = cnt(old.fl) - cnt(cur.fl); j; j = g[j].next)
    {
        if (g[j].v > 0)
            update(g[j].v, k + 1, st[g[j].v][k] + st[st[g[j].v][k].fa][k]);
        else if (d)
        {
            s[-g[j].v] -= d;
            if (s[-g[j].v] == 1)
                q.push(-g[j].v);
        }
    }
}
void dir(int i, bool f)
{
    int x = dep[u[i]] > dep[v[i]] ? u[i] : v[i];
    ans[i] = (u[i] == x) ^ f;
    update(x, 0, {st[x][0].fa, 0, f, !f});
}
void bfs()
{
    for (int u; q.size();)
    {
        u = q.front();
        q.pop();
        if (s[u] != 1)
            continue;
        node x = query(a[u], l[u]), y = query(b[u], l[u]);
        if (x.f2 || y.f1)
            continue;
        if (x.fl)
            dir(x.fl, 0);
        else
            dir(y.fl, 1);
    }
}
void solve()
{
    cin >> n >> m;
    for (int i = 1; i < n; ++i)
    {
        cin >> u[i] >> v[i];
        add(u[i], v[i]);
        add(v[i], u[i]);
    }
    build();
    for (int i = 1; i <= m; ++i)
    {
        cin >> a[i] >> b[i];
        l[i] = lca(a[i], b[i]);
        query(a[i], l[i], i);
        query(b[i], l[i], i);
        if (s[i] == 1)
            q.push(i);
    }
    fill(ans + 1, ans + n, -1);
    bfs();
    for (int i = 1; i < n; ++i)
    {
        if (ans[i] == -1)
        {
            dir(i, dep[u[i]] > dep[v[i]]);
            bfs();
        }
    }
    for (int i = 1; i < n; ++i)
        cout << ans[i];
    cout << endl;
}
int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);
    int _ = 1, __;
    cin >> __;
    init();
    while (_--)
        solve();
    return 0;
}

